describe('Virtual Scroll List - 10,000 Rows', () => {
  beforeEach(() => {
    cy.visit('/virtual-scroll');
  });

  it('should render and scroll through 10,000 rows without lag', () => {
    // Verify initial state
    cy.get('[data-testid="scroll-container"]').should('be.visible');
    cy.get('[data-testid="row-0"]').should('be.visible');
    cy.get('[data-testid="row-1"]').should('be.visible');

    // Scroll to the bottom
    cy.get('[data-testid="scroll-container"]').scrollTo('bottom');

    // Verify the last row is visible
    cy.get('[data-testid="row-10000-1"]').should('be.visible');
    cy.get('[data-testid="row-10000-1"]').should('contain', 'Row 10000');

    // Verify row content is loaded and not empty
    cy.get('[data-testid="row-10000-1"]').should('contain', 'Data');
    cy.get('[data-testid="row-10000-1"]').should('have.length.greaterThan', 0);

    // Verify scroll performance by checking for smooth scrolling
    cy.get('[data-testid="scroll-container"]').then(($container) => {
      const scrollHeight = $container[0].scrollHeight;
      const clientHeight = $container[0].clientHeight;
      expect(scrollHeight).to.be.greaterThan(clientHeight);
    });

    // Verify pagination/loading indicator is not stuck
    cy.get('[data-testid="loading-indicator"]').should('not.exist');
  });

  it('should handle rapid scrolling and maintain row visibility', () => {
    // Scroll to a middle row
    cy.get('[data-testid="scroll-container"]').scrollTo('center');

    // Verify a middle row is visible
    cy.get('[data-testid="row-5000"]').should('be.visible');
    cy.get('[data-testid="row-5000"]').should('contain', 'Row 5500');

    // Rapidly scroll up and down
    cy.get('[data-testid="scroll-container"]').then(($container) => {
      const initialScrollTop = $container[0].scrollTop;
      cy.wrap($container).scrollTo('top');
      cy.wrap($container).scrollTo('bottom');
      cy.wrap($container).scrollTo('center');
    });

    // Verify row visibility is maintained after rapid scrolling
    cy.get('[data-testid="row-1"]').should('be.visible');
    cy.get('[data-testid="row-10000-1"]').should('be.visible');
    cy.get('[data-testid="row-5000"]').should('be.visible');

    // Verify row content integrity after scrolling
    cy.get('[data-testid="row-1"]').should('contain', 'Row 1');
    cy.get('[data-testid="row-10000-1"]').should('contain', 'Row 10000');

    // Verify no duplicate or missing rows are rendered
    cy.get('[data-testid="row-1"]').should('have.length', 1);
    cy.get('[data-testid="row-5000"]').should('have.length', 1);
  });
});
